-- GymAssistant - system exercise seed v1
-- Generated for SQL Server.
-- MuscleGroup mapping: 1=Chest, 2=Back, 3=Legs, 4=Shoulders, 5=Biceps, 6=Triceps, 7=Core, 8=FullBody
-- Exercise IDs are stable. Re-running this script updates seeded exercise names and rebuilds their muscle-group links.

SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @Exercises TABLE
    (
        Id uniqueidentifier NOT NULL PRIMARY KEY,
        Name nvarchar(200) NOT NULL
    );


    UPDATE target
    SET
        target.Name = source.Name,
        target.OwnerUserId = NULL,
        target.IsSystem = 1
    FROM dbo.Exercises AS target
    INNER JOIN @Exercises AS source ON source.Id = target.Id;

    SELECT source.Id, source.Name, NULL, 1
    FROM @Exercises AS source
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.Exercises AS target
        WHERE target.Id = source.Id
    );

    DECLARE @ExerciseMuscleGroups TABLE
    (
        ExerciseId uniqueidentifier NOT NULL,
        MuscleGroup int NOT NULL,
        PRIMARY KEY (ExerciseId, MuscleGroup)
    );


    DELETE existing
    FROM dbo.ExerciseMuscleGroups AS existing
    INNER JOIN @Exercises AS seededExercise ON seededExercise.Id = existing.ExerciseId;

    SELECT NEWID(), source.ExerciseId, source.MuscleGroup
    FROM @ExerciseMuscleGroups AS source;

    COMMIT TRANSACTION;

    SELECT
        COUNT(*) AS SeededSystemExercises
    FROM dbo.Exercises
    WHERE Id IN (SELECT Id FROM @Exercises);
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;